// Module built with defaultIsolation(MainActor.self)
final class EditorModel {                    // implicitly @MainActor
    var document = Document()

    func export() async throws -> Data {
        try await Renderer.render(document)  // goes to background because of @concurrent
    }
}

enum Renderer {
    @concurrent
    static func render(_ doc: Document) async throws -> Data { /* CPU heavy */ Data() }
}
